fn push_script(c: &mut Command, body: &str) {
	#[cfg(windows)]
	if body.contains('\n') && !body.contains([' ', '\t']) {
		use std::os::windows::process::CommandExt;
		c.arg("-c").raw_arg(windows_quoted(body));
		return;
	}
	c.arg("-c").arg(body);
}

